new='''def recursive_finder(name, module_fqn, data, py_module_names, py_module_cache, zf):
    \"\"\"Collect module_utils dependencies with a work queue and write each once.\"\"\"
    module_utils_paths = [p for p in module_utils_loader._get_paths(subdirs=False) if os.path.isdir(p)]
    module_utils_paths.append(_MODULE_UTILS_PATH)
    pending = deque([(module_fqn, data)])
    queued = set()

    def add_file(parts, source, path):
        if parts in py_module_names:
            return
        py_module_names.add(parts)
        py_module_cache[parts] = (source, path)
        zf.writestr(os.path.join(*parts) + '.py', source)
        display.vvvvv(\"Using module_utils file %s\" % to_text(path, errors='surrogate_or_strict'))
        pending.append(('.'.join(parts), source))

    def add_parents(parts):
        # The top-level collection hierarchy needs packages too, even when
        # the collection leaves those directories as namespace packages.
        for count in range(1, len(parts)):
            parent = parts[:count]
            key = parent + ('__init__',)
            if key in py_module_names:
                continue
            source = b''
            path = os.path.join(*key) + '.py'
            if parts[0] == 'ansible' and count >= 2:
                relative = parent[2:]
                if relative:
                    try:
                        info = ModuleInfo(relative[-1], [os.path.join(p, *relative[:-1]) for p in module_utils_paths])
                        if info.pkg_dir:
                            source, path = info.get_source(), info.path
                    except ImportError:
                        pass
            elif parts[0] == 'ansible_collections' and count > 5:
                pkg = '.'.join(parent[:3])
                try:
                    actual = pkgutil.get_data(pkg, os.path.join(*parent[3:], '__init__.py'))
                except (IOError, OSError, ImportError):
                    actual = None
                if actual is not None:
                    source = actual
            add_file(key, source, path)

    # These files are required by the wrapper even when the caller prepopulated
    # the names set without writing the corresponding zip entries.
    bases = {
        ('ansible', '__init__'): b'from pkgutil import extend_path\\\\n__path__=extend_path(__path__,__name__)\\\\n',
        ('ansible', 'module_utils', '__init__'): b'from pkgutil import extend_path\\\\n__path__=extend_path(__path__,__name__)\\\\n',
    }
    existing = set(zf.namelist())
    for parts, source in bases.items():
        filename = os.path.join(*parts) + '.py'
        if filename not in existing:
            zf.writestr(filename, py_module_cache.get(parts, (source, filename))[0])
        py_module_names.add(parts)

    def locate(parts, ambiguous=False):
        if parts[:3] == ('ansible', 'module_utils', 'six'):
            parts = parts[:3]
            ambiguous = False
        if parts[:2] == ('ansible', 'module_utils'):
            return LegacyModuleUtilLocator(parts, ambiguous, module_utils_paths)
        if parts[:1] == ('ansible_collections',) and parts[3:5] == ('plugins', 'module_utils'):
            return CollectionModuleUtilLocator(parts, ambiguous)
        return None

    while pending:
        current_fqn, source = pending.popleft()
        try:
            tree = compile(source, '<unknown>', 'exec', ast.PyCF_ONLY_AST)
        except (SyntaxError, IndentationError) as error:
            raise AnsibleError(\"Unable to import %s due to %s\" % (name, error.msg))
        finder = ModuleDepFinder(current_fqn)
        finder.visit(tree)
        imports = set(finder.submodules)
        # The wrapper always imports basic to pass module arguments.
        imports.add(('ansible', 'module_utils', 'basic'))
        for parts in sorted(imports):
            if parts[:3] == ('ansible', 'module_utils', 'six'):
                parts = parts[:3]
            if parts in queued:
                continue
            queued.add(parts)
            locator = locate(parts, parts in finder.ambiguous_submodules)
            if locator is None:
                continue
            if not locator.found:
                raise AnsibleError('Could not find imported module support code for %s. Looked for (%s)' %
                                   (current_fqn, ', '.join(locator.candidate_names_joined())))
            result = locator.name_parts
            key = result + (('__init__',) if locator.is_package else ())
            add_parents(result)
            add_file(key, locator.source, locator.path)
            if locator.redirect_target:
                imports_target = locator.redirect_target
                # A redirect is a shim; its target must be shipped as well.
                if imports_target not in queued:
                    queued.add(imports_target)
                    target = locate(imports_target)
                    if target is None or not target.found:
                        candidates = target.candidate_names_joined() if target else ['.'.join(imports_target)]
                        raise AnsibleError('Could not find imported module support code for %s. Looked for (%s)' %
                                           (current_fqn, ', '.join(candidates)))
                    add_parents(target.name_parts)
                    add_file(target.name_parts + (('__init__',) if target.is_package else ()), target.source, target.path)
    py_module_cache.clear()

